CREATE TABLE cursos (
  nombre text PRIMARY KEY,
  profesor_jefe text NOT NULL
);
CREATE TABLE alumnos (
  rut text PRIMARY KEY,
  nombre text NOT NULL,
  curso text NOT NULL REFERENCES cursos (nombre)
);
CREATE TABLE telefonos_apoderado (
  rut_alumno text REFERENCES alumnos (rut) ON DELETE CASCADE,
  telefono text,
  PRIMARY KEY (rut_alumno, telefono)
);
CREATE TABLE talleres (
  nombre text PRIMARY KEY,
  profesor text NOT NULL,
  dia text NOT NULL,
  valor_mensual integer NOT NULL CHECK (valor_mensual >= 0)
);
CREATE TABLE inscripciones (
  rut_alumno text REFERENCES alumnos (rut),
  taller text REFERENCES talleres (nombre),
  inscrito_el date NOT NULL,
  PRIMARY KEY (rut_alumno, taller)
);
INSERT INTO cursos (nombre, profesor_jefe)
SELECT DISTINCT curso, profesor_jefe FROM planilla_talleres;
INSERT INTO alumnos (rut, nombre, curso)
SELECT DISTINCT rut_alumno, alumno, curso FROM planilla_talleres;
INSERT INTO telefonos_apoderado (rut_alumno, telefono)
SELECT DISTINCT rut_alumno, trim(t)
FROM planilla_talleres, regexp_split_to_table(telefonos_apoderado, ';') AS t;
INSERT INTO talleres (nombre, profesor, dia, valor_mensual)
SELECT DISTINCT taller, profesor_taller, dia, valor_mensual FROM planilla_talleres;
INSERT INTO inscripciones (rut_alumno, taller, inscrito_el)
SELECT rut_alumno, taller, inscrito_el FROM planilla_talleres;
WITH original AS (
  SELECT rut_alumno, alumno, curso, profesor_jefe, taller,
         profesor_taller, dia, valor_mensual, inscrito_el
  FROM planilla_talleres
), reconstruida AS (
  SELECT a.rut, a.nombre, a.curso, c.profesor_jefe, t.nombre,
         t.profesor, t.dia, t.valor_mensual, i.inscrito_el
  FROM inscripciones i
  JOIN alumnos a  ON a.rut = i.rut_alumno
  JOIN cursos c   ON c.nombre = a.curso
  JOIN talleres t ON t.nombre = i.taller
)
SELECT (SELECT count(*) FROM (TABLE original EXCEPT TABLE reconstruida) x) AS perdidas,
       (SELECT count(*) FROM (TABLE reconstruida EXCEPT TABLE original) y) AS inventadas;

