  socio_id bigint NOT NULL REFERENCES socios (id),
  fecha date NOT NULL,
  hora smallint NOT NULL CHECK (hora BETWEEN 8 AND 22),
  estado text NOT NULL DEFAULT 'pendiente' REFERENCES estados_reserva (codigo),
  creada_en timestamptz NOT NULL DEFAULT now(),
