CREATE TABLE pagos (
  reserva_id bigint PRIMARY KEY REFERENCES reservas (id),
  monto integer NOT NULL CHECK (monto > 0),
  medio text NOT NULL CHECK (medio IN ('debito', 'credito', 'transferencia')),
  pagado_en timestamptz NOT NULL DEFAULT now()
);
