exercises.solution:
CREATE TABLE clientes (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  rut text NOT NULL UNIQUE,
  nombre text NOT NULL,
  comuna text NOT NULL
);
CREATE TABLE restaurantes (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nombre text NOT NULL UNIQUE,
  comuna text NOT NULL
);
CREATE TABLE platos (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  restaurante_id integer NOT NULL REFERENCES restaurantes (id),
  nombre text NOT NULL,
  precio integer NOT NULL CHECK (precio > 0),
  UNIQUE (restaurante_id, nombre)
);
CREATE TABLE repartidores (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nombre text NOT NULL UNIQUE
);
CREATE TABLE pedidos (
  id integer PRIMARY KEY,
  cliente_id integer NOT NULL REFERENCES clientes (id),
  restaurante_id integer NOT NULL REFERENCES restaurantes (id),
  repartidor_id integer REFERENCES repartidores (id),
  creado_en timestamptz NOT NULL
);
CREATE TABLE pedido_items (
  pedido_id integer REFERENCES pedidos (id) ON DELETE CASCADE,
  plato_id integer REFERENCES platos (id),
  cantidad smallint NOT NULL CHECK (cantidad > 0),
  precio_unitario integer NOT NULL CHECK (precio_unitario > 0),
  PRIMARY KEY (pedido_id, plato_id)
);
INSERT INTO clientes (rut, nombre, comuna)
SELECT DISTINCT rut_cliente, cliente, comuna_cliente FROM planilla_delivery;
INSERT INTO restaurantes (nombre, comuna)
SELECT DISTINCT restaurante, comuna_restaurante FROM planilla_delivery;
INSERT INTO platos (restaurante_id, nombre, precio)
SELECT DISTINCT r.id, d.plato, d.precio
FROM planilla_delivery d
JOIN restaurantes r ON r.nombre = d.restaurante;
INSERT INTO repartidores (nombre)
SELECT DISTINCT repartidor FROM planilla_delivery WHERE repartidor IS NOT NULL;
INSERT INTO pedidos (id, cliente_id, restaurante_id, repartidor_id, creado_en)
SELECT DISTINCT d.pedido, c.id, r.id, rp.id, d.fecha_hora
FROM planilla_delivery d
JOIN clientes c          ON c.rut = d.rut_cliente
JOIN restaurantes r      ON r.nombre = d.restaurante
LEFT JOIN repartidores rp ON rp.nombre = d.repartidor;
INSERT INTO pedido_items (pedido_id, plato_id, cantidad, precio_unitario)
SELECT d.pedido, pl.id, d.cantidad, d.precio
FROM planilla_delivery d
JOIN restaurantes r ON r.nombre = d.restaurante
JOIN platos pl      ON pl.restaurante_id = r.id AND pl.nombre = d.plato;
